/**
 * Brand artwork for the downloadable Huddle guide, inlined as data URIs so the
 * exported file renders with no network access. Each image is stored at twice its
 * CSS display size, which keeps the export around 70 KB instead of the 1.1 MB the
 * reference file carried.
 *
 * Agent artwork is matched on the agent name because the Huddle catalogue has no
 * logo column yet. Move this to a HuddleAgent field once the content model has one.
 */

const FRONTIER_ACCELERATOR_LOGO = "data:image/png;base64,";
const SALES_AGENT_LOGO = "data:image/png;base64,";
const M365_COPILOT_LOGO = "data:image/png;base64,";

export const frontierAcceleratorLogo = FRONTIER_ACCELERATOR_LOGO;

export interface AgentArtwork {
  /** Inlined data URI for the agent logo. */
  source: string;
  /** Class the export stylesheet uses to size this particular logo. */
  className: string;
}

const AGENT_ARTWORK: ReadonlyArray<{ pattern: RegExp; artwork: AgentArtwork }> = [
  { pattern: /(microsoft\s*365|m365)\s*copilot/i, artwork: { source: M365_COPILOT_LOGO, className: "m365-copilot-logo" } },
  { pattern: /sales\s*(agent|chat|copilot)/i, artwork: { source: SALES_AGENT_LOGO, className: "agent-logo" } },
];

/** Returns inlined artwork for a known Microsoft agent, or null so the caller draws the CSS Copilot mark. */
export function agentArtwork(name: string): AgentArtwork | null {
  const trimmed = name.trim();
  if (!trimmed) return null;
  return AGENT_ARTWORK.find((entry) => entry.pattern.test(trimmed))?.artwork ?? null;
}
